export default GRAPH_DATA;

/** Empty graph shown until the scoped backend responds. Never seed the UI
 *  with the walkthrough snapshot — those datasource IDs belong to another
 *  workspace and look like a permission leak. */
export function emptyDataset(workspace = ''): GraphDataset {
  return {
    nodes: [],
    edges: [],
    meta: {
      workspace,
      source: 'empty',
      nodeCount: 0,
      edgeCount: 0,
      byLayer: { MG: 0, TG: 0, KG: 0, UG: 0 },
    },
  };
}

/** Deep-copied demo snapshot so consumers can't mutate the module constant. */
export function demoDataset(): GraphDataset {
  return JSON.parse(JSON.stringify(GRAPH_DATA)) as GraphDataset;
}
